def dihedral(X):
 return [X, np.rot90(X,1),np.rot90(X,2),np.rot90(X,3),np.fliplr(X),np.flipud(X),X.T,np.fliplr(np.rot90(X,1))]
Bs=[[A[i*6:(i+1)*6,j*6:(j+1)*6] for j in range(4)] for i in range(4)]
for i in range(4):
 for j in range(4):
  matches=[]
  for p in range(4):
   for q in range(4):
    for k,X in enumerate(dihedral(Bs[p][q])):
     if np.array_equal(Bs[i][j],X):matches.append((p,q,k))
  print((i,j),matches[:4], 'n',len(matches))

def orb(r,c,n=24):
 return {(r,c),(c,n-1-r),(n-1-r,n-1-c),(n-1-c,r),(r,n-1-c),(n-1-r,c),(c,r),(n-1-c,n-1-r)}
nonrecover=[]; rec={}
for r,c in coords:
 o=orb(int(r),int(c)); known=[(x,y,int(A[x,y])) for x,y in o if A[x,y]!=2]
 if known: rec[(int(r),int(c))]=known
 else: nonrecover.append((int(r),int(c),len(o)))
print('nonrecover',nonrecover)
print('recover',len(rec))

B=A.copy()
conflicts=[]
for r,c in coords:
 vals=[int(A[x,y]) for x,y in orb(int(r),int(c)) if A[x,y]!=2]
 if len(set(vals))!=1: conflicts.append(((r,c),vals))
